-- CA_0239_la_special_districts_batch1.sql
-- CA_0239: LA County special districts -- Water Replenishment District of Southern California, West Basin Municipal Water District, Central Basin Municipal Water District, Three Valleys Municipal Water District, Upper San Gabriel Valley Municipal Water District, San Gabriel Valley Municipal Water District.
--
-- MODEL (new: the DB had NO special-district rows at all -- no government, chamber, district, polygon or office):
--   per special district: one government ("<District>, California, US", LOCAL) + one chamber (its board);
--   by-division boards: one LOCAL district + one polygon per division (geo_id 'ca-spd-<slug>-div-N'), one office each;
--   at-large boards: one LOCAL district + one polygon for the whole district, one office per seat.
--   Polygons use the NEW geofence layer mtfcc 'X-CA-SPD' (operator decision 2026-09-24): GEOFENCE_DISTRICT_JOIN and
--   MTFCC_DISTRICT_TYPE_GUARD admit LOCAL for any X layer other than X0001-X0004, so no code change is needed. The
--   app shows these boards in the Representatives tab, Local tier, one accordion per district (government_name).
-- POLYGONS: LA RR/CC master precinct layer (public.gis.lacounty.gov/.../Political_Boundaries/MapServer/34, 33,236
--   precincts) dissolved by the district's DST_x code / DIV_x division. DIV_x = the director division number (checked
--   against each district's own division descriptions -- see per-district notes). LA County portion only (AVEK and
--   SCV Water also reach Kern / Ventura). Slivers < 1e-8 deg2 dropped, simplified at 2e-6 deg, make_valid, and any
--   residual overlap between two divisions of one district given to the lower-numbered division. Local QA: each
--   district's divisions union to its whole-district dissolve (ratio >= 0.99999), max pair overlap < 1e-9 deg2.
--   Special districts legitimately overlap one another and cities / school districts; that is expected.
-- DIRECTORS: each district's own board page (read 2026-09-24), cross-checked with RR/CC candidate lists + results for
--   Nov 2022 (id 4300) and Nov 2024 (4324). Term start: Nov-election winners YYYY-12-01 'month' 'elected'; appointed
--   in lieu of election: YYYY-12-01 'month' 'appointed'; board appointees: the appointment date. Party is never stored.
-- CANDIDATES: RR/CC Nov 3 2026 list (lavote.gov/Apps/CandidateList/Index?id=4348); only names whose nomination papers
--   were FILED (arg[8]); ballot designation = the line under the name. ONLY CONTESTS ON THE BALLOT are seeded
--   (operator decision 2026-09-24): where filed candidates <= seats up, the seat is appointed in lieu of election
--   (Elections Code 10515) and no race is created; the current holder stays seated. Incumbents (RR/CC flag E/A) are
--   linked to the seated director; challengers unlinked.
-- RACES go on '2026 LA County General' (d91a20ce-557e-4615-a31b-5b2b3df2ed14); primary_party NULL.
-- Apply with: npx tsx scripts/_apply-file.ts <abs path>   (geometry-heavy; do not paste through MCP).
--
-- Water Replenishment District of Southern California (by division, 5 seats; RR/CC DST WR WR; https://www.wrd.org/board-profiles):
--   Director (Division 1): Joy Langford -- elected 2022-12-01 (month)
--   Director (Division 2): Robert Katherman -- elected 2024-12-01 (month)
--   Director (Division 3): John D. S. Allen -- elected 2022-12-01 (month)
--   Director (Division 4): Sergio Calderon -- elected 2022-12-01 (month)
--   Director (Division 5): Vera Robles DeWitt -- elected 2024-12-01 (month)
-- West Basin Municipal Water District (by division, 5 seats; RR/CC DST MWD WB; https://www.westbasinca.gov/about-west-basin/board-of-directors):
--   Director (Division 1): Tommy Faavae -- appointed 2025-02-01 (month)
--   Director (Division 2): Gloria D. Gray -- appointed 2022-12-01 (month) [reused row 7a04bf87]
--   Director (Division 3): Desi Alvarez -- elected 2024-12-01 (month)
--   Director (Division 4): Scott Houston -- elected 2022-12-01 (month) [reused row 8af59b1a]
--   Director (Division 5): Donald L. Dear -- elected 2024-12-01 (month)
-- Central Basin Municipal Water District (by division, 4 seats; RR/CC DST MWD CB; https://www.centralbasin.org/administration/board-of-directors/meet-the-board):
--   Director (Division 1): Leticia Vasquez Wilson -- elected 2024-12-01 (month)
--   Director (Division 2): Gary Mendez -- elected 2024-12-01 (month) [reused row f349bad2]
--   Director (Division 3): Arturo Chacon -- elected 2022-12-01 (month)
--   Director (Division 4): Juan Garza -- elected 2024-12-01 (month) [reused row 4f735057]
-- Three Valleys Municipal Water District (by division, 7 seats; RR/CC DST MWD TV; https://www.threevalleys.com/board-of-directors):
--   Director (Division 1): Carlos Goytia -- elected 2022-12-01 (month)
--   Director (Division 2): David De Jesus -- elected 2024-12-01 (month)
--   Director (Division 3): VACANT -- Division III vacant since June 3 2026 (Jeff Hanlon resigned); https://www.threevalleys.com/board-of-directors/division-iii
--   Director (Division 4): Bob Kuhn -- appointed 2024-12-01 (month)
--   Director (Division 5): Jody Roberto -- appointed 2022-12-01 (month)
--   Director (Division 6): Jorge Marquez -- elected 2024-12-01 (month) [reused row 5ccde213]
--   Director (Division 7): Mike Ti -- appointed 2024-12-01 (month)
-- Upper San Gabriel Valley Municipal Water District (by division, 5 seats; RR/CC DST MWD US; https://upperwater.org/leadership/):
--   Director (Division 1): Anthony Fellow -- elected 2022-12-01 (month)
--   Director (Division 2): Charles Treviño -- elected 2024-12-01 (month)
--   Director (Division 3): Ed Chavez -- appointed 2024-12-01 (month)
--   Director (Division 4): Katarina Garcia -- appointed 2024-12-01 (month)
--   Director (Division 5): Jennifer Santana -- elected 2022-12-01 (month)
-- San Gabriel Valley Municipal Water District (by division, 5 seats; RR/CC DST MWD SG; https://sgvmwd.com/our-leadership/):
--   Director (Division 1): Mark R. Paulson -- appointed 2022-12-01 (month)
--   Director (Division 2): Steven T. Placido -- elected 2024-12-01 (month)
--   Director (Division 3): Mike Eng -- appointed 2024-12-01 (month)
--   Director (Division 4): Miles Prince -- appointed 2022-12-01 (month)
--   Director (Division 5): Bruce Knoles -- appointed 2022-12-01 (month)
--
-- BATCH NOTES:
--   ON THE BALLOT (6 races / 19 candidates): WRD Div 3 (OPEN: John Allen did not file; 4 candidates) and Div 4; West
--     Basin Div 1 and Div 2; Three Valleys Div 3 (seat VACANT since June 3 2026 -- Jeff Hanlon resigned to seek a district
--     staff job, and now runs again as a non-incumbent); SGV MWD Div 5 (OPEN: Bruce Knoles did not file).
--   APPOINTED IN LIEU (one filer per seat, no race): WRD Div 1 (Langford), West Basin Div 4 (Houston), Central Basin Div
--     3 (Chacon), Three Valleys Div 1 (Goytia) and Div 5 (Roberto) -- RR/CC Notice of No Election published 2026-08-26
--     (threevalleys.com/uploads/files/Board/260825 Notice of No Election.pdf), Upper SGV Div 1 (Fellow) and Div 5
--     (Santana), SGV MWD Div 1 (Paulson) and Div 4 (Prince). Holders stay seated.
--   DIVISION CHECK: a representative point of each dissolved division falls in the communities the district itself lists
--     (West Basin 1 Rancho Palos Verdes / 2 Inglewood / 3 Redondo Beach / 4 El Segundo / 5 Gardena; Three Valleys 1 Pomona
--     / 3 Claremont / 4 Glendora / 7 Rowland Heights; Upper SGV 2 Rosemead / 4 West Covina / 5 Baldwin Park; SGV MWD 1
--     Alhambra / 3 Monterey Park / 4 Sierra Madre / 5 Azusa; Central Basin 1 Paramount / 3 Commerce; WRD 3 Long Beach, 4
--     Bell area).
--   Central Basin also has 3 APPOINTED at-large directors (purveyor / large-user / city seats) -- not modeled (not
--     elected by residents).
--   REUSED ROWS: Gloria D. Gray (Inglewood Council D1 row; also a 2026 Inglewood Mayor candidate), Robert Gonzales
--     (Azusa Council D5 row; ballot designation 'Azusa Councilmember'), Jorgel Chavez (Bell Gardens Council row;
--     designation 'Infrastructure Consultant/Councilmember'), and 2024 NetFile filer rows for Scott Houston, Gary Mendez,
--     Juan Garza, Jorge Marquez.
BEGIN;

-- ─── 1. Government + governing board (chamber) per special district (none existed) ─────────
INSERT INTO essentials.governments (id, name, type, state)
SELECT v.id, v.name, 'LOCAL', 'CA'
  FROM (VALUES
    ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'Water Replenishment District of Southern California, California, US'),
    ('eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'West Basin Municipal Water District, California, US'),
    ('d0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, 'Central Basin Municipal Water District, California, US'),
    ('6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, 'Three Valleys Municipal Water District, California, US'),
    ('797cd578-cf50-51d2-845d-8400a25d4913'::uuid, 'Upper San Gabriel Valley Municipal Water District, California, US'),
    ('3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid, 'San Gabriel Valley Municipal Water District, California, US')
  ) AS v(id, name)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments g WHERE g.id = v.id);

INSERT INTO essentials.chambers (id, government_id, name, name_formal, term_length, election_frequency, website_url, policy_engagement_level)
SELECT v.id, v.gid, v.name, v.name_formal, '4 years', '2 years', v.url, 'full'   -- slug is generated
  FROM (VALUES
    ('603abfbc-1d59-5ba1-8c99-e1ba7c98bc1e'::uuid, 'b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'Board of Directors', 'Water Replenishment District of Southern California Board of Directors', 'https://www.wrd.org/board-profiles'),
    ('272eb7ad-e818-585b-9384-dbb559fd560f'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'Board of Directors', 'West Basin Municipal Water District Board of Directors', 'https://www.westbasinca.gov/about-west-basin/board-of-directors'),
    ('bb844ce1-dc93-5ab0-8e68-37ce4ba1de4f'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, 'Board of Directors', 'Central Basin Municipal Water District Board of Directors', 'https://www.centralbasin.org/administration/board-of-directors/meet-the-board'),
    ('dce9fe41-152b-5407-b716-a421159ec292'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, 'Board of Directors', 'Three Valleys Municipal Water District Board of Directors', 'https://www.threevalleys.com/board-of-directors'),
    ('3bf795dd-f0c4-5188-8a95-72c496bf4bc0'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, 'Board of Directors', 'Upper San Gabriel Valley Municipal Water District Board of Directors', 'https://upperwater.org/leadership/'),
    ('612d34e2-967a-57c0-a29a-46913d3f3ebf'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid, 'Board of Directors', 'San Gabriel Valley Municipal Water District Board of Directors', 'https://sgvmwd.com/our-leadership/')
  ) AS v(id, gid, name, name_formal, url)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = v.id);

