-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X-CA-SPD' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry) AND public.ST_SRID(gb.geometry) = 4326;
  IF n <> 31 THEN RAISE EXCEPTION 'expected 31 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid) AND d.district_type = 'LOCAL' AND d.mtfcc = 'X-CA-SPD';
  IF n <> 31 THEN RAISE EXCEPTION 'expected 31 LOCAL districts, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE d.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid);
  IF n <> 31 THEN RAISE EXCEPTION 'expected 31 offices, got %', n; END IF;

  -- every held seat is held by exactly the director named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('aa138ab7-d30d-5bda-a4bf-57572f156728'::uuid, 'e569ab1d-d9cf-5364-82c8-faaca133921e'::uuid), ('7d81e7d2-1056-5693-b494-c503e27d0853'::uuid, '829f140f-cc2d-54d4-9d8f-b50da3803f94'::uuid), ('c46b164a-bec5-559a-9afc-2b7aac446af3'::uuid, '0b809e74-7df2-5c60-9cc0-abab36bfa37d'::uuid), ('4bacc432-dd72-577c-885a-61cacd9b48c9'::uuid, '84767a7c-37b6-5968-ac3f-426a9d6f3568'::uuid), ('c785ecff-6fc1-5ec4-83da-77c27ce75066'::uuid, '91684327-a5a5-5e79-85b6-6ac07d110578'::uuid), ('09e9e913-110f-5365-b84e-752bab2662e8'::uuid, '939c52a4-660b-5e99-96f5-fae35e94ed01'::uuid), ('e1e4c2f5-e96b-58aa-baba-917574a80e96'::uuid, '7a04bf87-ab95-4ae7-a142-9899662637b1'::uuid), ('68a9b4b0-1564-5405-a110-3b7075300b2e'::uuid, 'f75ffcce-70a8-5f01-b3e0-f8a48e6e36fe'::uuid), ('3aa0e81e-0358-5da1-98ec-174c0ecaa7ca'::uuid, '8af59b1a-fbfb-411f-bd8b-5c8ffca3a619'::uuid), ('7a4da545-d851-563b-8041-dcc0482076de'::uuid, '7535e059-b39e-5b84-acc1-18d7325e68b5'::uuid), ('941176fe-2762-5d20-852d-0040d012a89e'::uuid, '8a3b0c8a-6042-5e8a-9663-161cc92ef870'::uuid), ('2e94425e-2f3c-55fa-97ba-64b9388dab2a'::uuid, 'f349bad2-e1f3-49b3-9919-bbd2b18367e2'::uuid), ('ae04a901-31b5-5d1c-92b5-a2e200d58e1e'::uuid, 'f0ae3ba4-dfd5-5008-8fa3-1ab573f772c5'::uuid), ('19fe04f5-2c03-5571-bfc4-16aecec296cd'::uuid, '4f735057-d546-4376-ae93-72a879e95f51'::uuid), ('cb955224-acc2-5fb0-9d16-dba23ddd6699'::uuid, 'd2aaf62b-7182-52db-a4db-2d98e884a848'::uuid), ('e92475b2-a186-52b4-b39c-6ddf4d8b6624'::uuid, 'd7236433-9329-5731-aeec-92e7cae3341c'::uuid), ('2bef41e5-19c4-5d07-92c0-2c89f503efd0'::uuid, 'a1a0aaa3-b1e7-5206-8659-f04583c8bd64'::uuid), ('ed2fa202-17e5-54ba-9284-0bbd37a64479'::uuid, '7e6492f7-37cc-53ad-828d-d4e0717e0372'::uuid), ('d5bbd45c-b143-5aaf-a52f-635faef10a02'::uuid, '5ccde213-f414-4062-ad03-539f957ca7e5'::uuid), ('54b34075-4e21-5705-a9af-c5c98fde4021'::uuid, '673251bb-3a59-5a92-ba7c-67929c67a6dc'::uuid), ('4c5ca7f5-efb7-57f8-bd25-2f39823d446a'::uuid, 'bef97572-173f-598c-9251-aba04aac8fb2'::uuid), ('b5439c9f-e27b-5d4f-b925-aa1a5dea1fed'::uuid, '62cf3478-5acf-5458-aad9-7a272e576f04'::uuid), ('529ebe1f-db1d-529c-9b9f-c40e115e74fc'::uuid, '39d48290-b92c-58f7-a501-073bc40aa998'::uuid), ('d021d454-0631-512b-a81b-29f249c8e50f'::uuid, '383722b7-e4d3-5be5-95a6-15481f3e5b89'::uuid), ('554d19b4-adf7-5e42-8451-299691681752'::uuid, 'e8c50c74-9c63-59e3-90cb-fc1489ae8826'::uuid), ('7a6f25f9-228d-5e89-9ac4-ae5a55516bf8'::uuid, 'ac928949-2fbd-5395-acf8-22cce4f0b8f2'::uuid), ('2b6e965f-66e4-5b63-b688-1476af4358c9'::uuid, '9ecdd412-c187-5dbb-8bd8-a7648a42878f'::uuid), ('f7b31dbf-beab-50c3-ae45-104bad2ddad8'::uuid, 'c5a50b55-281f-5e6a-81aa-b0e44e2ff5d7'::uuid), ('dcb9531e-0865-5bf8-a232-005aa116721c'::uuid, 'b2343503-b83b-5e8d-aed2-06aac1b5212b'::uuid), ('8ab37cd9-c692-5a4a-ab4a-08ef7faa8dd1'::uuid, '3923b907-f94e-5900-9c32-2afee009b4c9'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n <> 30 THEN RAISE EXCEPTION 'expected 30 seats each held by its named director, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('aa138ab7-d30d-5bda-a4bf-57572f156728'::uuid, 'e569ab1d-d9cf-5364-82c8-faaca133921e'::uuid), ('7d81e7d2-1056-5693-b494-c503e27d0853'::uuid, '829f140f-cc2d-54d4-9d8f-b50da3803f94'::uuid), ('c46b164a-bec5-559a-9afc-2b7aac446af3'::uuid, '0b809e74-7df2-5c60-9cc0-abab36bfa37d'::uuid), ('4bacc432-dd72-577c-885a-61cacd9b48c9'::uuid, '84767a7c-37b6-5968-ac3f-426a9d6f3568'::uuid), ('c785ecff-6fc1-5ec4-83da-77c27ce75066'::uuid, '91684327-a5a5-5e79-85b6-6ac07d110578'::uuid), ('09e9e913-110f-5365-b84e-752bab2662e8'::uuid, '939c52a4-660b-5e99-96f5-fae35e94ed01'::uuid), ('e1e4c2f5-e96b-58aa-baba-917574a80e96'::uuid, '7a04bf87-ab95-4ae7-a142-9899662637b1'::uuid), ('68a9b4b0-1564-5405-a110-3b7075300b2e'::uuid, 'f75ffcce-70a8-5f01-b3e0-f8a48e6e36fe'::uuid), ('3aa0e81e-0358-5da1-98ec-174c0ecaa7ca'::uuid, '8af59b1a-fbfb-411f-bd8b-5c8ffca3a619'::uuid), ('7a4da545-d851-563b-8041-dcc0482076de'::uuid, '7535e059-b39e-5b84-acc1-18d7325e68b5'::uuid), ('941176fe-2762-5d20-852d-0040d012a89e'::uuid, '8a3b0c8a-6042-5e8a-9663-161cc92ef870'::uuid), ('2e94425e-2f3c-55fa-97ba-64b9388dab2a'::uuid, 'f349bad2-e1f3-49b3-9919-bbd2b18367e2'::uuid), ('ae04a901-31b5-5d1c-92b5-a2e200d58e1e'::uuid, 'f0ae3ba4-dfd5-5008-8fa3-1ab573f772c5'::uuid), ('19fe04f5-2c03-5571-bfc4-16aecec296cd'::uuid, '4f735057-d546-4376-ae93-72a879e95f51'::uuid), ('cb955224-acc2-5fb0-9d16-dba23ddd6699'::uuid, 'd2aaf62b-7182-52db-a4db-2d98e884a848'::uuid), ('e92475b2-a186-52b4-b39c-6ddf4d8b6624'::uuid, 'd7236433-9329-5731-aeec-92e7cae3341c'::uuid), ('2bef41e5-19c4-5d07-92c0-2c89f503efd0'::uuid, 'a1a0aaa3-b1e7-5206-8659-f04583c8bd64'::uuid), ('ed2fa202-17e5-54ba-9284-0bbd37a64479'::uuid, '7e6492f7-37cc-53ad-828d-d4e0717e0372'::uuid), ('d5bbd45c-b143-5aaf-a52f-635faef10a02'::uuid, '5ccde213-f414-4062-ad03-539f957ca7e5'::uuid), ('54b34075-4e21-5705-a9af-c5c98fde4021'::uuid, '673251bb-3a59-5a92-ba7c-67929c67a6dc'::uuid), ('4c5ca7f5-efb7-57f8-bd25-2f39823d446a'::uuid, 'bef97572-173f-598c-9251-aba04aac8fb2'::uuid), ('b5439c9f-e27b-5d4f-b925-aa1a5dea1fed'::uuid, '62cf3478-5acf-5458-aad9-7a272e576f04'::uuid), ('529ebe1f-db1d-529c-9b9f-c40e115e74fc'::uuid, '39d48290-b92c-58f7-a501-073bc40aa998'::uuid), ('d021d454-0631-512b-a81b-29f249c8e50f'::uuid, '383722b7-e4d3-5be5-95a6-15481f3e5b89'::uuid), ('554d19b4-adf7-5e42-8451-299691681752'::uuid, 'e8c50c74-9c63-59e3-90cb-fc1489ae8826'::uuid), ('7a6f25f9-228d-5e89-9ac4-ae5a55516bf8'::uuid, 'ac928949-2fbd-5395-acf8-22cce4f0b8f2'::uuid), ('2b6e965f-66e4-5b63-b688-1476af4358c9'::uuid, '9ecdd412-c187-5dbb-8bd8-a7648a42878f'::uuid), ('f7b31dbf-beab-50c3-ae45-104bad2ddad8'::uuid, 'c5a50b55-281f-5e6a-81aa-b0e44e2ff5d7'::uuid), ('dcb9531e-0865-5bf8-a232-005aa116721c'::uuid, 'b2343503-b83b-5e8d-aed2-06aac1b5212b'::uuid), ('8ab37cd9-c692-5a4a-ab4a-08ef7faa8dd1'::uuid, '3923b907-f94e-5900-9c32-2afee009b4c9'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated director row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two divisions of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X-CA-SPD'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X-CA-SPD'
   WHERE a.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid) AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% division pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> LOCAL district -> office -> holder)
  -- to exactly that district's own director(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X-CA-SPD'
   WHERE me.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'LOCAL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X-CA-SPD'
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id AND och.politician_id IS NOT NULL);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own director(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid);
  IF n <> 6 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 6 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid);
  IF n <> 19 THEN RAISE EXCEPTION 'expected 19 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a director seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('b01127e7-0c1a-5629-9087-0f8d91964ef7'::uuid, 'eed1bdb1-b3cf-5167-8440-ba0e808883a9'::uuid, 'd0445234-aeaa-5b8b-a2e1-86c7e8be271e'::uuid, '6f398b67-32b2-5700-9fbc-069056c271ee'::uuid, '797cd578-cf50-51d2-845d-8400a25d4913'::uuid, '3e2c43e9-fcdd-5f25-a4b1-95472ea8ed90'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated director', n; END IF;

  RAISE NOTICE 'CA_0239 applied: 6 boards, 31 polygons, 31 seats (30 held), 6 races, 19 candidates';
END $$;

COMMIT;
